			"id": str(card.get("participant_id", "")),
			"can_select": bool(card.get("can_select", false)),
			"card_state": str(card.get("card_state", "")),
			"rect": Rect2(Vector2(x, y), card_size),
			"card": card,
		})
		x += card_size.x + gap.x


